import React from 'react';
// Import suitable icons for a clinic
import { FaClipboardList, FaHeartbeat, FaComments } from 'react-icons/fa';

// --- Data for the feature cards ---
const featuresData = [
  {
    icon: <FaClipboardList size={30} />,
    title: 'Personalized Diet Plans',
    description: 'Receive custom meal plans tailored to your health goals, lifestyle, and dietary preferences. No generic advice, only what works for you.',
  },
  {
    icon: <FaHeartbeat size={30} />,
    title: 'Lifestyle Coaching',
    description: 'We go beyond food, helping you build sustainable habits around sleep, stress, and physical activity for holistic well-being.',
  },
  {
    icon: <FaComments size={30} />,
    title: 'Ongoing Support',
    description: 'Stay motivated with regular follow-ups and continuous support via WhatsApp & email. We are with you at every step of your journey.',
  },
];


// --- Main Features Component ---
const Features = () => {
  return (
    <section style={styles.featuresSection}>
      <div style={styles.container}>
        {featuresData.map((feature, index) => (
          <div key={index} style={styles.card}>
            <div style={styles.iconContainer}>
              {feature.icon}
            </div>
            <h3 style={styles.cardTitle}>{feature.title}</h3>
            <p style={styles.cardDescription}>{feature.description}</p>
          </div>
        ))}
      </div>
    </section>
  );
};


// --- Styles ---
const styles = {
  featuresSection: {
    backgroundColor: '#1a202c', // Matches your header/footer background
    padding: '64px 24px',
    fontFamily: 'sans-serif',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
    display: 'flex',
    justifyContent: 'center',
    gap: '32px', // Space between cards
    flexWrap: 'wrap', // Allows cards to stack on smaller screens
  },
  card: {
    backgroundColor: '#2d3748', // Card background, same as pricing cards
    padding: '32px',
    borderRadius: '16px', // Rounded corners
    width: '320px',
    textAlign: 'center',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    border: '1px solid #4a5568',
  },
  iconContainer: {
    // This creates the white square background for the icon from the image
    backgroundColor: '#e2e8f0', 
    color: '#1a202c', // Dark icon color for contrast
    width: '60px',
    height: '60px',
    borderRadius: '8px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: '24px',
  },
  cardTitle: {
    color: '#ffffff',
    fontSize: '1.5rem',
    fontWeight: 'bold',
    margin: '0 0 16px 0', // Margin bottom
  },
  cardDescription: {
    color: '#a0aec0',
    fontSize: '1rem',
    lineHeight: '1.6',
    margin: 0,
  },
};

export default Features;
